func (f *TxForwarder) ctxWithTimeout() (context.Context, context.CancelFunc) {
	if f.timeout == time.Duration(0) {
		return context.WithCancel(f.ctx)
	}
	return context.WithTimeout(f.ctx, f.timeout)
}

